contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Try to withdraw `amount` from c as this contract (msg.sender == this).
    // We take `amount` as parameter and ensure this test contract can receive Ether.
    function run(uint256 amount) public payable {
        // record contract balance before
        uint256 beforeContractBalance = address(c).balance;

        bool reverted;
        c.withdraw(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterContractBalance = address(c).balance;

        // If withdraw succeeded, the contract's balance must have decreased by at least amount.
        // (We cannot read the internal per-address balances mapping, so we express the rule in terms
        // of the observable contract balance decrease and the fact that a successful withdraw implies
        // the contract sent Ether out.)
        assert(reverted || beforeContractBalance >= afterContractBalance && (beforeContractBalance - afterContractBalance) >= amount);
    }

    // allow receiving Ether when c transfers to this test contract
    receive() external payable { }
}

